/* ShiftReady - sound files, embedded as base64 so they also work when index.html is opened by double-click.
   Processed copies are in assets/audio/.
     click:   sonido_4.mp3: bright and short (any button)
     option:  sonido_3.mp3: clean ding (choosing a reply; notifications play it twice, lower = alert)
     send:    sonido_6.mp3: firm pop (send, close chat, start shift)
     menu:    sonido_7.mp3: soft (open chats, tabs, documents, panels)
     back:    sonido_8.mp3: low (close, back, switches)
     success: vadim_makes_sound-modern-success-confirmation-notification-566072.mp3 (chat closed, shift complete)
     welcome: "audio de voz.mp4": "Welcome to ShiftReady, a customer service simulator."
     howto:   "voz.mp4": "Hi there! Welcome to the simulator. Here you will improve your problem-solving skills. Please press Start Shift and I wish you good luck!"
*/
window.SR = window.SR || {};
SR.sounds = {
  click: { type: "audio/wav", data: "" },
  option: { type: "audio/wav", data: "" },
  send: { type: "audio/wav", data: "" },
  menu: { type: "audio/wav", data: "" },
  back: { type: "audio/wav", data: "" },
  success: { type: "audio/mpeg", data: "" },
  welcome: { type: "audio/mpeg", data: "" },
  howto: { type: "audio/mpeg", data: "" }
};

/* The page loads this file after it is on screen: tell boot.js the voice is here */
try { document.dispatchEvent(new Event('sr:sounds')); } catch (e) { /* old browser */ }
